pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that always reverts on transferFrom
        TokenReverter token = new TokenReverter();
        address[] memory tos = new address[](1);
        tos[0] = address(0x1);
        bool ok;
        try c.transfer(address(this), address(token), tos, 100) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference version reverts because call fails, so ok = false => assertTrue(!ok) holds
        // The buggy version requires(!_s) which passes, so ok = true => assertTrue(!ok) fails
        assertTrue(!ok);
    }
}

contract TokenReverter {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
