pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a dummy token that always fails transferFrom
        address dummyToken = address(new TokenThatFails());
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint value = 100;

        // Attempt transfer - reference reverts, second version returns true
        bool ok;
        try c.transfer(from, dummyToken, tos, value) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference requires _s so it reverts (ok=false), but second version doesn't require so it succeeds (ok=true)
        // We assert that the call succeeded - this will pass on reference (because it reverts -> ok=false, so assertTrue(ok) fails) 
        // Wait - we need the opposite: assertion passes on reference, fails on bug.
        // Reference reverts => ok=false; bug doesn't revert => ok=true.
        // So to make assertion pass on reference, we should assertFalse or assertEq(ok, false)
        // But the instruction says assertTrue(<concrete fact reading c>).
        // We can assert that the call reverted (ok == false).
        // That passes on reference (ok==false) and fails on bug (ok==true).
        assertTrue(!ok);
    }
}

contract TokenThatFails {
    function transferFrom(address, address, uint256) public pure returns (bool) {
        return false; // always fail
    }
}

