pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // A mock ERC20 token that reverts on zero-value transfers (non-payable)
    contract MockToken {
        function transferFrom(address, address, uint256 amount) external pure returns (bool) {
            require(amount > 0, "zero value");
            return true;
        }
    }

    function testRegression_property() public {
        MockToken token = new MockToken();
        address from = address(0xdead);
        address[] memory tos = new address[](1);
        tos[0] = address(0xbeef);
        uint amount = 0; // zero value causes revert in reference

        bool callOk;
        // The reference version will revert because require(_s) fails when token.transferFrom returns false
        // The buggy version will succeed because it drops the require (the call returns false but no check)
        // We catch the revert to test both versions consistently
        vm.prank(from);
        try c.transfer(from, address(token), tos, amount) {
            callOk = true;
        } catch {
            callOk = false;
        }
        // Assertion: reference version reverts (callOk == false), buggy version returns true (callOk == true)
        assertTrue(callOk == false);
    }
}

