contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a token that makes transferFrom always revert
        RevertingToken token = new RevertingToken();
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 100;
        // Call transfer; it will attempt call to token which reverts
        bool ok;
        try c.transfer(from, address(token), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference version reverts (ok==false); buggy version succeeds (ok==true)
        // So assert true for the reference (false) fails? Wait: we want test to PASS on reference (ok==false) and FAIL on buggy (ok==true).
        // So we assert that ok == false.
        assertTrue(!ok);
    }
}

contract RevertingToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        revert("always revert");
    }
}

